-- RRC048: MariaDB10.11, dedicated fresh admin session; manual coordinated application only.
-- Source recipe facts/provenance: batch.public.json. No engine/updater/version/rule changes.
-- Anonymous compound block: no permanent helper procedure or migration table.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE already_present INT DEFAULT 0;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 requires fresh transaction-free session'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 strict SQL mode required'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('tradeskill_recipe','tradeskill_recipe_entries','items') AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 InnoDB foundation mismatch'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe')<>16 OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 recipe schema column-count mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc048_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc048_parents LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc048_parent_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc048_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc048_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 START TRANSACTION;
 SET own_transaction=TRUE;
 IF EXISTS(SELECT 1 FROM rrc048_parents e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 legacy icecream producer changed'; END IF;
 IF EXISTS(SELECT 1 FROM rrc048_parent_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc048_parents p ON p.id=r.recipe_id)<>159 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 legacy icecream entries changed'; END IF;
 SELECT COUNT(*) INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*) INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*) INTO already_present FROM tradeskill_recipe r JOIN rrc048_recipes e ON r.id=e.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM rrc048_items e LEFT JOIN items i ON i.id=e.id WHERE i.id IS NULL OR BINARY i.Name<>BINARY e.name) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 item identity/dependency mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE itemclass=1 AND ((id=17906 AND bagtype=14 AND bagslots=10) OR (id=54256 AND bagtype=15 AND bagslots=10) OR (id=17164 AND bagtype=15 AND bagslots=6) OR (id=72502 AND bagtype=54 AND bagslots=8) OR (id IN (54443,66633) AND bagtype=54 AND bagslots=10)))<>6 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 native baking container mismatch'; END IF;
 IF already_present NOT IN (0,143) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 partial batch or ID collision'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe r JOIN rrc048_recipes e ON r.tradeskill=e.tradeskill AND r.name=e.name WHERE r.id<>e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 existing recipe-name collision'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc048_entries e ON r.item_id=e.item_id JOIN rrc048_recipes q ON e.recipe_id=q.id WHERE e.successcount>0 AND e.componentcount=0 AND e.iscontainer=0 AND r.successcount>r.componentcount AND r.iscontainer=0 AND r.recipe_id<>e.recipe_id AND NOT((e.item_id=15961 AND e.recipe_id IN (3092822,3092900,3092907) AND r.recipe_id IN (3092822,3092900,3092907)) OR (e.item_id=33644 AND e.recipe_id IN (3092881,3092882,3092883) AND r.recipe_id IN (3092881,3092882,3092883)) OR (e.item_id=75818 AND e.recipe_id IN (3092819) AND r.recipe_id IN (1624)) OR (e.item_id=75822 AND e.recipe_id IN (3092821) AND r.recipe_id IN (1631)) OR (e.item_id=75007 AND e.recipe_id IN (3092835) AND r.recipe_id IN (1785)) OR (e.item_id=75019 AND e.recipe_id IN (3092837) AND r.recipe_id IN (1789)) OR (e.item_id=75012 AND e.recipe_id IN (3092838) AND r.recipe_id IN (1790)) OR (e.item_id=75030 AND e.recipe_id IN (3092839) AND r.recipe_id IN (1793)) OR (e.item_id=75006 AND e.recipe_id IN (3092840) AND r.recipe_id IN (1794)) OR (e.item_id=75024 AND e.recipe_id IN (3092841) AND r.recipe_id IN (1797)) OR (e.item_id=75819 AND e.recipe_id IN (3092842) AND r.recipe_id IN (1799)) OR (e.item_id=75825 AND e.recipe_id IN (3092843) AND r.recipe_id IN (1801)) OR (e.item_id=75817 AND e.recipe_id IN (3092844) AND r.recipe_id IN (1802)) OR (e.item_id=75018 AND e.recipe_id IN (3092847) AND r.recipe_id IN (1808)) OR (e.item_id=75034 AND e.recipe_id IN (3092849) AND r.recipe_id IN (1829)) OR (e.item_id=75015 AND e.recipe_id IN (3092852) AND r.recipe_id IN (1832)) OR (e.item_id=75009 AND e.recipe_id IN (3092854) AND r.recipe_id IN (1833)) OR (e.item_id=75029 AND e.recipe_id IN (3092870) AND r.recipe_id IN (1814)) OR (e.item_id=75008 AND e.recipe_id IN (3092888) AND r.recipe_id IN (2018)) OR (e.item_id=75020 AND e.recipe_id IN (3092890) AND r.recipe_id IN (2020)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 existing output recipe collision'; END IF;
 IF already_present=0 THEN
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc048_recipes e ON r.recipe_id=e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 orphan target entries collision'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM rrc048_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 recipe postimage mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc048_entries e LEFT JOIN tradeskill_recipe_entries r ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE r.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 expected entry absent'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc048_recipes q ON q.id=r.recipe_id LEFT JOIN rrc048_entries e ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE e.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 foreign/different target entries'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc048_recipes q ON q.id=r.recipe_id)<>929 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 target entry multiplicity mismatch'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before+IF(already_present=0,143,0) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before+IF(already_present=0,929,0) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 unexpected table row-count delta'; END IF;
 IF EXISTS(SELECT 1 FROM rrc048_parents e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 legacy icecream producer changed'; END IF;
 IF EXISTS(SELECT 1 FROM rrc048_parent_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc048_parents p ON p.id=r.recipe_id)<>159 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC048 legacy icecream entries changed'; END IF;
 DROP TEMPORARY TABLE rrc048_parents;
 DROP TEMPORARY TABLE rrc048_parent_entries;
 DROP TEMPORARY TABLE rrc048_entries;
 DROP TEMPORARY TABLE rrc048_recipes;
 DROP TEMPORARY TABLE rrc048_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC048' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
